        className: "language-java",
        children: "public final class CycleDetector {\n    private enum VisitState {\n        VISITING,\n        VISITED\n    }\n\n    public boolean hasCycle(Map<NodeId, List<NodeId>> graph) {\n        Map<NodeId, VisitState> states = new HashMap<>();\n\n        for (NodeId node : graph.keySet()) {\n            if (hasCycleFrom(node, graph, states)) {\n                return true;\n            }\n        }\n\n        return false;\n    }\n\n    private boolean hasCycleFrom(\n        NodeId node,\n        Map<NodeId, List<NodeId>> graph,\n        Map<NodeId, VisitState> states\n    ) {\n        VisitState state = states.get(node);\n\n        if (state == VisitState.VISITING) {\n            return true;\n        }\n\n        if (state == VisitState.VISITED) {\n            return false;\n        }\n\n        states.put(node, VisitState.VISITING);\n\n        for (NodeId next : graph.getOrDefault(node, List.of())) {\n            if (hasCycleFrom(next, graph, states)) {\n                return true;\n            }\n        }\n\n        states.put(node, VisitState.VISITED);\n\n        return false;\n    }\n}\n"
      })
