      children: _jsx(_components.code, {
        className: "language-java",
        children: "public List<NodeId> topologicalSort(Map<NodeId, List<NodeId>> graph) {\n    Map<NodeId, Integer> indegree = new HashMap<>();\n\n    for (NodeId node : graph.keySet()) {\n        indegree.putIfAbsent(node, 0);\n\n        for (NodeId next : graph.getOrDefault(node, List.of())) {\n            indegree.merge(next, 1, Integer::sum);\n        }\n    }\n\n    Queue<NodeId> ready = new ArrayDeque<>();\n\n    for (Map.Entry<NodeId, Integer> entry : indegree.entrySet()) {\n        if (entry.getValue() == 0) {\n            ready.offer(entry.getKey());\n        }\n    }\n\n    List<NodeId> result = new ArrayList<>();\n\n    while (!ready.isEmpty()) {\n        NodeId node = ready.poll();\n\n        result.add(node);\n\n        for (NodeId next : graph.getOrDefault(node, List.of())) {\n            int newDegree = indegree.merge(next, -1, Integer::sum);\n\n            if (newDegree == 0) {\n                ready.offer(next);\n            }\n        }\n    }\n\n    if (result.size() != indegree.size()) {\n        throw new IllegalStateException(\"Graph has cycle\");\n    }\n\n    return result;\n}\n"
      })
